// axioms.eg — constraints guard one compartment; an axiom guards the whole program.
// A user axiom is checked after every top-level statement; breaking it halts the program.

compartment Account {
  id = "co-account-001"
  state { balance: 100, owner: null }
  constraint solvent hard { state.balance >= 0 }
  constraint owned hard { len(state.owner) > 0 }
  on "deposit" (ev) { state.balance += ev.amount }
  on "withdraw" (ev) { state.balance -= ev.amount }
  on "claim" (ev) { state.owner = ev.owner }
}
on "rejected" (r) { print("refused", r.signal, "—", r.constraint) }
on "gap.opened" (g) { print("gap:", g.message) }

var audit_total = 100
axiom BOOKS_BALANCE { Account.state.balance == audit_total }

// owner is null, so "owned" cannot be evaluated: that is a gap, and the state does not change
emit "deposit" { amount: 50 }
print("balance before an owner:", Account.state.balance)

fn deposit(n) {
  audit_total += n
  emit "deposit" { amount: n }
}

emit "claim" { owner: "james" }
deposit(50)                        // one statement: the audit and the account move together
emit "withdraw" { amount: 500 }    // refused by solvent: the books still balance
print("owner", Account.state.owner, "balance", Account.state.balance)

emit "withdraw" { amount: 30 }     // goes through, but audit_total is not updated...
print("unreachable: the axiom halts on the line above")

// components.eg — components are bounded, versioned units that talk only through typed hooks, joined by wires.
// The wiring is the program's architecture: `eg components components.eg` exports it as loom records.

component Sensor {
  id = "sensor.raw"
  namespace = "sensor"
  version = "1.0.0"
  intent = "turn raw readings into typed samples"
  state { seen: 0 }

  boundary counts_up { state.seen >= 0 }

  in reading(r: { value: num, unit: string }) {
    if r.unit != "C" { raise("Sensor only speaks Celsius, got {r.unit}") }
    state.seen += 1
    emit out sample { n: state.seen, celsius: r.value }
  }
  out sample: { n: num, celsius: num }
}

component Smoother {
  id = "sensor.smoother"
  namespace = "sensor"
  version = "1.1.0"
  intent = "moving average over the last 3 samples"
  state { window: [] }

  boundary bounded_window { len(state.window) <= 3 }

  in sample(s: { n: num, celsius: num }) {
    var w = push(state.window, s.celsius)
    if len(w) > 3 { w = slice(w, 1) }
    state.window = w
    emit out smoothed { celsius: round(sum(w) / len(w) * 10) / 10, of: len(w) }
  }
  out smoothed: { celsius: num, of: num }

  fn latest() = state.window[-1]
}

component Alarm {
  id = "sensor.alarm"
  namespace = "sensor"
  version = "1.0.0"
  state { limit: 30, tripped: false }

  boundary sane_limit { state.limit > 0 and state.limit < 100 }

  in check(t: { celsius: num, of: num }) {
    if t.celsius > state.limit and not state.tripped {
      state.tripped = true
      emit out alert { celsius: t.celsius }
    }
  }
  in configure(c: { limit: num }) { state.limit = c.limit }
  out alert: { celsius: num }
}

