// primitives.eg — dynamic primitives: a kind is the schema for a primitive, a template makes instances at run time.
//
//   kind      what any component claiming it must have (hooks + shapes, typed state, boundary count, fns)
//   template  a parameterised component; spawn T("id", …) makes a live instance with its own state and uuid
//   wire      connects instances held in variables, at run time; despawn removes one and drops its wires

kind Stage {
  require version
  in take(x: { v: num })
  out give: { v: num }
  state { count: num }
  boundary_count 1..2
}

kind Filter is Stage {          // everything a Stage needs, plus a way to ask what it let through
  fn passed()
}

template Scale(factor: num) is Stage {
  namespace = "pipe"
  version = "1.0.0"
  state { count: 0 }
  boundary non_negative_count { state.count >= 0 }
  in take(x: { v: num }) {
    state.count += 1
    emit out give { v: x.v * factor }
  }
  out give: { v: num }
}

template Clamp(lo: num, hi: num) is Filter {
  namespace = "pipe"
  version = "1.0.0"
  state { count: 0, kept: 0 }
  boundary ordered { lo <= hi }
  in take(x: { v: num }) {
    state.count += 1
    if x.v >= lo and x.v <= hi {
      state.kept += 1
      emit out give { v: x.v }
    }
  }
  out give: { v: num }
  fn passed() = state.kept
}

// build a pipeline from data, at run time
fn make(step) {
  if step.op == "scale" { return spawn Scale(step.id, step.arg) }
  if step.op == "clamp" { return spawn Clamp(step.id, step.lo, step.hi) }
  raise("unknown op {step.op}")
}

fn chain(stages) {
  wire "input" -> stages[0].take
  for i in 1..len(stages) {
    let prev = stages[i - 1]
    let next = stages[i]
    wire prev.give -> next.take
  }
  let last = stages[-1]
  wire last.give -> "output"
}

let plan = [
  { op: "scale", id: "double", arg: 2 },
  { op: "clamp", id: "band", lo: 0, hi: 15 },
  { op: "scale", id: "half", arg: 0.5 },
]
let stages = plan |> map(make)
chain(stages)

on "output" (o) { print("  out:", o.v) }

print("pipeline:", stages |> map(fn(s) = s.name) |> join(" → "))
for v in [3, 6, 9, -1] {
  print("in:", v)
  emit "input" { v: v }
}

let band = stages[1]
print("band let through", band.passed(), "of", band.state.count)
print("is a Filter?", is_kind(band, "Filter"), "| is a Stage?", is_kind(band, "Stage"), "| double a Filter?", is_kind(stages[0], "Filter"))
print("Scale instances:", instances("Scale") |> map(fn(s) = s.id))

// speculate: what if the band were wider? despawn, spawn and rewire inside a whatif — none of it survives
let wide_ids = whatif {
  despawn band
  let wider = spawn Clamp("wide", -100, 100)
  wire stages[0].give -> wider.take
  wire wider.give -> stages[2].take
  emit "input" { v: 50 }
  instances("Clamp") |> map(fn(s) = s.id)
}
print("in the branch the Clamps were", wide_ids, "— for real they are", instances("Clamp") |> map(fn(s) = s.id))

// a template's parameters can break its own boundary: that instance is refused at spawn
try { spawn Clamp("upside-down", 10, 1) } else e { print("refused:", e.message) }

// despawn for real: the band's wires go with it
despawn band
print("after despawn:", len(components().wires), "wires;", len(instances("Clamp")), "Clamp instances")
try { print(band.state) } else e { print("stale handle:", e.message) }
print("ledger ok:", ledger_verify())

// tests.eg — run with: eg test tests.eg   (eg run skips test blocks)

compartment Stack {
  id = "co-stack-001"
  state { items: [] }
  constraint bounded hard { len(state.items) <= 3 }
  on "push" (ev) { state.items = push(state.items, ev.x) }
  on "pop" { state.items = slice(state.items, 0, len(state.items) - 1) }
  fn top() = state.items[-1]
}
on "rejected" (r) { record "overflow" { signal: r.signal } }

fn gcd(a: num, b: num): num {
  if b == 0 { return a }
  return gcd(b, a % b)
}

test "gcd" {
  expect gcd(48, 18) == 6
  expect gcd(7, 5) == 1
}

test "stack pushes and pops" {
  emit "push" { x: 1 }
  emit "push" { x: 2 }
  expect Stack.top() == 2
  emit "pop"
  expect Stack.state.items == [1]
}

test "stack refuses a fourth item" {
  for x in [1, 2, 3, 4] { emit "push" { x: x } }
  expect len(Stack.state.items) == 3, "bounded should hold"
  expect len(ledger() |> filter(fn(e) = e.kind == "overflow")) == 1
}

test "each test starts from the same world" {
  expect Stack.state.items == [], "earlier tests leaked state"
}

test "this one fails on purpose" {
  expect 1 + 1 == 3, "arithmetic still works"
}

print("top level ran; tests run under eg test")

// whatif.eg — speculative branches: fork the world, look, and leave it untouched.

compartment Tank {
  id = "co-tank-001"
  state { level: 50 }
  constraint not_overflowing hard { state.level <= 100 }
  constraint not_empty hard { state.level >= 0 }
  on "fill" (ev) { state.level += ev.amount }
  on "drain" (ev) { state.level -= ev.amount }
}
on "rejected" (r) { print("  (refused: {r.constraint})") }

fn try_fill(amount) = whatif {
  emit "fill" { amount: amount }
  Tank.state.level
}

for amount in [10, 40, 60] {
  print("if we filled {amount}: level would be", try_fill(amount))
}
print("real level is still", Tank.state.level)

// pick the largest safe fill by speculation, then do it for real
let candidates = [5, 25, 45, 65]
let safe = candidates |> filter(fn(a) = try_fill(a) == Tank.state.level + a)
print("safe fills:", safe)
emit "fill" { amount: max(safe) }
print("filled:", Tank.state.level)

// random() draws from the run's seed — and a whatif does not use up the real world's draws
let peek = whatif { random() }
let real = random()
print("same draw?", peek == real)
print("ledger ok:", ledger_verify())
